#!/usr/bin/env node
/**
 * Run only AFTER the custom domain, HTTPS, mailbox and published site are
 * verified. No permanent QR asset is generated by the website build.
 * Requires qrencode, a local CLI tool; no external QR service is used.
 */
import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import path from 'node:path';

const args = process.argv.slice(2);
const value = (key, fallback) => {
  const index = args.indexOf(key);
  return index >= 0 ? args[index + 1] : fallback;
};
const fail = (message) => {
  throw new Error(message);
};
const requiredConfirmations = ['--confirm-domain-live', '--confirm-email-working'];
for (const flag of requiredConfirmations) {
  if (!args.includes(flag)) {
    fail(`QR creation is locked. Verify the official domain/HTTPS and mailbox first, then explicitly supply ${flag}. No QR files were created.`);
  }
}

const origin = 'https://thrivingmindsconsulting.com';
const destinationPath = value('--path', '/');
const allowedPaths = ['/', '/#book-now', '/#resources'];
if (!allowedPaths.includes(destinationPath)) {
  fail('Use --path /, /#book-now, or /#resources. Other destinations must be reviewed before adding them.');
}
const purpose = value('--purpose', 'primary');
if (!/^[a-z0-9-]{1,48}$/.test(purpose)) fail('Purpose must be a short lowercase filename, not a URL or personal information.');
const destination = destinationPath === '/' ? origin : `${origin}${destinationPath}`;

const response = await fetch(origin, { signal: AbortSignal.timeout(15_000), redirect: 'follow' });
if (!response.ok || new URL(response.url).origin !== origin) {
  fail('The intended official HTTPS domain did not return a successful same-domain response. No QR files were created.');
}
const html = await response.text();
if (
  !/<meta\s+name="application-name"\s+content="Thriving Minds Consulting"/i.test(html) ||
  !html.includes(`href="${origin}/"`)
) {
  fail('The official domain does not appear to serve the prepared Thriving Minds build with the expected canonical. No QR files were created.');
}
const health = await fetch(`${origin}/api/healthz`, { signal: AbortSignal.timeout(10_000) });
const healthBody = await health.json().catch(() => null);
if (!health.ok || healthBody?.status !== 'ok') fail('The published inquiry API is not reachable. Finish launch verification before generating QR codes.');

const tool = spawnSync('qrencode', ['--version'], { encoding: 'utf8' });
if (tool.error || tool.status !== 0) fail('Install the local qrencode CLI before generating print assets. No external QR service is needed.');

const root = path.resolve(import.meta.dirname, '../..');
const output = path.join(root, 'attached_assets/launch-qr', purpose);
await mkdir(output, { recursive: true });
const base = path.join(output, purpose);
for (const format of ['SVG', 'PNG']) {
  const result = spawnSync('qrencode', [
    '-l', 'H', '-m', '4', '-s', '12',
    '--foreground=4E2A4A', '--background=FFFFFF',
    '-t', format, '-o', `${base}.${format.toLowerCase()}`, destination,
  ], { encoding: 'utf8' });
  if (result.error || result.status !== 0) fail(`QR encoding failed: ${result.error?.message || result.stderr}`);
}
const qr = (await readFile(`${base}.png`)).toString('base64');
const logo = (await readFile(path.join(root, 'artifacts/thriving-minds/public/thriving-minds-logo.png'))).toString('base64');
await writeFile(`${base}-print.html`, `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Thriving Minds — ${purpose} QR print card</title>
<style>
body{margin:0;background:#fdfbf7;color:#4e2a4a;font:16px/1.5 Arial,sans-serif}
main{width:100mm;box-sizing:border-box;margin:10mm auto;padding:7mm;background:#fff;text-align:center;border:1px solid #ddd}
.logo{width:37mm;height:37mm;object-fit:contain}.qr{display:block;width:65mm;height:65mm;margin:4mm auto;image-rendering:pixelated}
h1{font-size:14px;letter-spacing:.07em;line-height:1.6}p{font-size:11px;overflow-wrap:anywhere}
@media print{body{background:#fff}main{margin:0 auto;break-inside:avoid}}
</style></head><body><main>
<img class="logo" alt="Thriving Minds Consulting" src="data:image/png;base64,${logo}">
<h1>SCAN. CONNECT.<br>TAKE YOUR NEXT STEP.</h1>
<img class="qr" alt="QR code linking to ${destination}" src="data:image/png;base64,${qr}">
<p>${destination}</p></main></body></html>`);
await writeFile(`${base}-verification.txt`, `Destination: ${destination}
Generated: ${new Date().toISOString()}
Official-domain HTTPS response and prepared canonical checked automatically.
Operator explicitly confirmed domain and mailbox checks.
REQUIRED BEFORE PRINTING: scan the PNG, SVG and a printed sample with multiple phones, confirm destination, and test the inquiry flow.
Quiet zone: 4 modules. Error correction: H. Do not crop, place a logo over modules, or print smaller than 25 mm.
`);
process.stdout.write(`QR assets prepared at ${path.relative(root, output)}. Scan using multiple phones and a printed sample BEFORE distributing them.\n`);